      "conceptExplanation": "보세전시장은 박람회·전람회·견본품 전시회 등의 운영을 위하여 외국물품을 장치·전시하거나 사용할 수 있는 특허보세구역이다(관세법 제190조). 위원회는 매년 ①'전시'와 '사용'의 정의 ②회기 종료(폐회) 후 외국물품의 처리 ③수입신고 수리 전 판매·인도(사용) 제한, 이 세 축을 반복 출제한다.\n\n[1] '전시'와 '사용'의 정의(보세전시장 운영에 관한 고시):\n- '전시'에는 전시 대상 물품의 성능을 실연하기 위하여 이를 작동시키는 행위가 포함된다.\n- '사용'에는 (가)그 물품의 성질 또는 수량에 변경을 가하는 행위, (나)전시장에서 그 물품을 소비하는 행위가 포함된다. 즉 보세전시장에서는 단순 전시뿐 아니라 일정 범위의 사용·소비가 허용된다.\n\n[2] 회기 종료(폐회) 후 물품처리:\n- 원칙: 박람회 등 회기가 종료되면 보세전시장에 있는 외국물품은 외국으로 반송함을 원칙으로 한다.\n- 국내 반입: 기증·매각 등으로 외국물품을 국내로 반입하려는 자는 수입신고를 하여야 한다.\n- 폐기: 폐기하려면 미리 세관장의 승인을 받아야 하고, 폐기 후 잔존물에 가치가 있으면 폐기 후의 성질·수량에 따라 관세를 부과한다.\n- 잔여물품 반출: 회기가 종료되고 반송·수입·폐기처리되지 아니한 외국물품은 '해당 보세전시장의 특허기간 내에' 다른 보세구역으로 반출하여야 한다(별도의 '특허기간 만료 후 30일 유예'는 없음).\n\n[3] 수입신고 수리 전 판매·인도 제한:\n- 보세전시장에 장치된 판매용 외국물품은 수입신고가 수리되기 전에는 사용할 수 없다.\n- 전시용 외국물품을 현장에서 직매하더라도 수입신고가 수리되기 전에는 구매자에게 인도할 수 없다(외국물품을 국내로 반입하려면 수입통관이 선행되어야 함). 다만 판매 목적 외국물품의 '반입' 자체는 가능하다.",
      "trapAnalysis": "함정의 핵심은 '기간·시점'과 '단정 표현'을 비트는 데 있다.\n\n(1) 잔여물품 반출 시점 비틀기(2023 no.1·2025 no.2): 정답 선지 ④는 '특허기간 만료 후 30일 이내'라는 그럴듯한 유예기간을 끼워 넣었다. 그러나 잔여 외국물품은 '해당 보세전시장의 특허기간 내에' 다른 보세구역으로 반출해야 하고 별도의 '만료 후 30일 유예'는 규정에 없다. '~일 이내'라는 숫자만 보고 옳다고 넘기면 틀린다.\n\n(2) '사용'의 정의 포함/불포함 비틀기(2021 no.11·2022 no.11·2024 no.8·2025 no.2): '사용에는 성질·수량 변경, 전시장 소비가 포함된다'가 옳은 진술인데, 이를 '포함하지 아니한다'로 뒤집거나(2022 ②·나), '사용·소비행위는 금지된다'로 단정하면(2019 ①②) 오답이다.\n\n(3) 수입신고 '수리' 누락(2021 no.11): '판매용 물품은 수입신고 후 사용할 수 있다'처럼 '수리'를 빠뜨리고 '신고 후'로만 쓰면 함정이다. 사용·인도는 신고가 아니라 신고 '수리' 후에 가능하다.\n\n(4) 판매 목적 물품 반입 일률 금지 비틀기(2023 no.2·2024 no.8): '판매할 것을 목적으로 하는 외국물품은 반입할 수 없다'는 단정은 오답이다. 반입은 가능하고, 다만 수입신고 수리 후 인도하는 절차 제한이 따를 뿐이다.\n\n(5) 직매 시 인도 시점(2019 no.10·2022 no.11): '현장 직매 시 수리 전에 인도할 수 있다'는 오답, '수리 전에는 인도할 수 없다'가 정답.",
      "answerKey": "정답은 ④다. ④는 반송·수입·폐기되지 않은 잔여 외국물품의 반출 시점을 '특허기간 만료 후 30일 이내'라고 했으나, 실제로는 '해당 보세전시장의 특허기간 내에' 다른 보세구역으로 반출하여야 하며 '만료 후 30일'이라는 유예기간 규정은 없다. 기간 부분이 규정과 달라 틀린 진술이므로 정답이다.\n\n①(회기 종료 시 외국 반송 원칙), ②(국내 반입 시 수입신고), ③(폐기 시 미리 세관장 승인), ⑤(폐기 후 잔존물에 가치가 있으면 폐기 후 성질·수량에 따라 과세)는 모두 보세전시장 폐회 후 처리 규정과 일치하는 옳은 진술이다.",
