        "시내면세점 '매장'은 판매장소이지 인도장이 아니다(2019 no.3 정답). 인도장은 출국장·선내·통관우체국 세관통관장소·항공화물탁송 보세구역·입국장 보세구역·세관장 지정 보세구역(자유무역지역 포함)",
