      "lawBasis": "관세법 제196조(보세판매장)·제196조의2(시내보세판매장 및 입국장 보세판매장의 운영), 관세법 시행규칙 제69조의3(출국 내국인 구매한도, 2022.3.18 폐지 전), 관세법 시행규칙 제69조의4(입국장 면세점 구매한도 및 별도 면세품목), 보세판매장 운영에 관한 고시.",
      "sourceRef": "위험물산업기사가 아닌 보세사 기출 — 보세사 2과목(보세구역관리) 기출 출처: 2020년 18·20번, 2021년 6·7번, 2024년 1번, 2025년 4번 (대표문항: 2025년 4번). 데이터 파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-2-2025.js (외 2020·2021·2024)"
