      "lawBasis": "관세법 제197조(종합보세구역의 지정 등 - 관세청장 지정), 제198조(종합보세사업장의 설치·운영에 관한 신고 등 - 세관장 신고·기능변경 신고), 제199조(종합보세구역에의 물품의 반입·반출 등), 제200조(반출입물품의 범위 등·장치기간 무제한), 제202조(설비의 유지의무 등), 제204조(종합보세구역 지정의 취소 등 - 기능수행 정지 6개월 범위); 종합보세구역의 지정 및 운영에 관한 고시(예정지역 3년, 기능별 구분 관리, House B/L 단위 반출입신고, 장기보관화물 매각 절차)",
      "sourceRef": "보세사 기출 2과목(보세구역관리) - 2025년 24번(대표문항), 2024년 5·6번, 2022년 7번, 2021년 12·20번, 2020년 21번(전항정답), 2019년 23번. 파일: claude/previews/tradelogix-nexus/bosesa-data-2-2025.js 외 연도별 데이터. 출처 kinz.kr 기출, Claude 법령근거 해설 재작성(2026-06-14)."
