        "활어장치장은 CCTV 영상을 상시 녹화할 수 있고 녹화된 영상을 30일 이상 보관할 수 있는 감시장비를 보유해야 한다.",
        "세관장이 CCTV 영상을 인터넷망을 통해 실시간으로 확인이 가능하도록 조치해야 한다.",
