      "conceptExplanation": "보세공장 과세에는 '제품과세'와 '원료과세' 두 축이 있다. ① 제품과세(관세법 제188조 본문): 외국물품 또는 외국물품+내국물품을 원료·재료로 가공한 작업으로 생긴 물품(제품)은 '외국으로부터 우리나라에 도착한 물품'으로 본다. 즉 완성된 제품 자체를 외국물품으로 보아 제품 상태(성질·수량)로 과세하는 것이 원칙이다. 다만 세관장의 승인을 받아 외국물품과 내국물품을 '혼용'한 경우에는, 그로써 생긴 제품 중 외국물품의 가격(종량세 물품은 수량)이 차지하는 비율에 상응하는 분만 외국물품으로 보아 과세한다(혼용 안분계산, 제188조 단서). ② 원료과세(관세법 제189조): 보세공장에서 제조된 물품을 수입하는 경우, 운영인이 '사용신고 전에 미리' 세관장에게 원료과세 적용을 신청하면, 그 제품의 원료인 외국물품에 대해 '사용신고를 할 때(사용신고 시)'의 그 원료의 성질 및 수량에 따라 관세를 부과한다. 즉 과세물건(과세대상)이 제품이 아니라 '투입 원료'로 바뀌고, 과세 기준시점이 '사용신고 시점'이다. 원료과세는 통상 완제품보다 원료 세율이 낮을 때(세번 변경으로 세율이 올라가는 경우) 운영인에게 유리하다. ③ 원료과세 포괄(일괄)적용(관세법 시행령 제205조 제3항): ㉠ 최근 2년간 생산하여 판매된 물품 중 수출된 물품의 가격 비율이 100분의 50 이상이거나, ㉡ 내·외국 원재료별 품명·규격·소요량·재고 등이 전산시스템에 의해 명확하게 기록·관리되는 경우에는 '1년의 범위'에서 원료별·제품별 또는 보세공장 전체에 대하여 원료과세를 일괄(포괄)하여 신청할 수 있다(AEO 등 일정 요건). 핵심 함정은 제품과세·원료과세 모두 과세 기준시점을 '수입신고할 때'로 바꿔치기하는 것이며, 원료과세의 정답 시점은 항상 '사용신고를 할 때'이다.",
      "trapAnalysis": "최빈출 함정은 원료과세의 '과세 기준시점' 바꿔치기다. 선지 ③은 다른 부분(사용신고 전 미리 신청)은 정확히 써두고 결정적 시점만 '수입신고할 때'로 슬쩍 바꿔놓았다. 정답은 '사용신고를 할 때'의 원료 성질·수량이다. 출제자는 '사용신고 전에 신청한다'는 절차 표현을 그대로 살려 수험생이 앞 문장 일치만 보고 옳다고 넘기도록 유도한다. 또 다른 단골 함정은 ① 제품과세를 원료과세로, 또는 그 반대로 정의를 뒤바꾸는 것, ② 혼용 안분계산 시 '외국물품 비율에 상응하는 분'을 '전부' 또는 '내국물품 비율'로 바꾸는 것, ③ 포괄적용 수출비율을 '50% 이상'이 아니라 '60% 이상' 등으로 바꾸는 것(2021년 #1 나 선지에서 '100분의 60'으로 출제됨), ④ 신청 시한을 '사용신고 전'이 아니라 '수입신고 전'으로 바꾸는 것(2021년 #1 마 선지)이다.",
      "answerKey": "정답은 ③. 원료과세는 사용신고 전에 미리 신청한 경우 '사용신고를 할 때'의 원료의 성질 및 수량에 따라 관세를 부과하는데(관세법 제189조), ③은 기준시점을 '수입신고할 때'로 잘못 적어 틀렸다. ① 제품과세(제188조 본문)로 옳음 — 외국물품(또는 외국+내국물품)을 가공한 제품은 외국에서 도착한 물품으로 본다. ② 혼용 안분계산(제188조 단서)으로 옳음 — 세관장 승인 혼용 시 제품 중 외국물품의 수량·가격에 상응하는 분만 외국물품으로 본다. ④ 포괄(일괄)원료과세 요건으로 옳음 — 최근 2년간 수출비율 50% 이상이고 AEO인 보세공장은 1년 범위에서 원료별·제품별·전체로 일괄 신청 가능. ⑤ 옳음 — 품명·규격 동일·손모율 무변동 동종물품 혼용 시 새 혼용승인신청 생략 가능.",
