      "conceptExplanation": "보세공장 장외작업(=보세공장 외 작업, 관세법 제187조·보세공장 운영에 관한 고시)은 보세작업상 필요할 때 세관장의 '허가'를 받아 보세공장 밖의 장소에서 보세작업의 일부(또는 외국에서 수리·가공 목적으로 일시 수출하는 경우 등)를 수행하는 제도다. 핵심 효과·절차는 다음 4가지로 정리된다. ① 의제(간주): 허가받은 보세공장 외 작업장에 반입된 외국물품은 '지정된 기간(허가기간)이 만료될 때까지는' 보세공장에 있는 것으로 본다. 즉 장외작업장도 허가기간 동안은 법적으로 보세공장의 연장으로 취급되어 외국물품 상태가 유지된다. ② 허가기간 경과 시 즉시징수: 지정된 허가기간이 지난 후에도 그 작업장에 허가된 외국물품이 남아 있을 때에는, 세관장은 '반입명령'을 하는 것이 아니라 해당 물품의 허가를 받은 보세공장의 '운영인'으로부터 그 관세를 '즉시 징수'한다(허가기간이 끝나면 더 이상 보세공장 의제가 유지되지 않아 외국물품이 국내에 반입된 것으로 보아 과세). ③ 장기소요 2년: 세관장은 물품 1단위 생산에 장기간이 소요된다고 인정하는 경우 '2년의 범위'에서 장외작업을 허가할 수 있다(또한 거대중량 등 사유로 계속 장치 시 1년 범위 연장 승인 가능, 임가공계약서 등으로 전체 내용을 미리 알 수 있는 여러 건의 일괄허가도 1년 이내). ④ 절차: 세관장은 허가신청을 받은 날부터 '10일 이내'에 허가 여부를 통지하고, 장외작업 허가를 받은 자는 허가기간이 끝나는 날부터 '5일 이내'에 작업완료 결과를 통보해야 한다. 또한 장외작업 물품은 장외작업장소에 장치한 상태에서 원보세공장 관할세관으로 수출·수입신고·양수도·반출신고 등을 할 수 있고, 원보세공장 관할세관이 관리하되 곤란하면 장외작업장 관할세관장에게 관리·감독을 의뢰할 수 있다.",
      "trapAnalysis": "이 유형의 핵심 함정은 '숫자(기간)'와 '조치 내용·상대방'을 미세하게 바꿔 오답을 만드는 것이다. (1) 장기소요 시 허가기간을 '2년'이 정답인데 '5년' 또는 '3년'으로 바꿔 출제(2024 #24, 2023 #21의 연계 함정). 다른 보세작업 기간(특허기간 10년, 장치기간 1년 등)과 헷갈리게 만든다. (2) 허가기간 경과 시 조치를 '운영인으로부터 관세 즉시징수'가 옳은데, '세관장이 지체없이 보세공장 반입명령을 하여야 한다'로 바꿔 출제(2023 #21 정답①). 즉시징수의 상대방을 '화주'로 바꾸는 변형도 가능하다(화주 X, 운영인 O). (3) 의제 기준을 '허가기간(지정기간) 만료 시까지'가 옳은데 다른 시점으로 바꾸거나, 의제 자체를 부정하는 변형. (4) 허가/신고 혼동: 장외작업은 '허가'사항인데 '신고'로 바꾸는 함정(보세건설장 장외작업도 동일하게 허가). (5) 통지 10일·결과통보 5일을 서로 바꾸거나 다른 숫자로 변형.",
      "answerKey": "정답은 ④. 물품 1단위 생산에 장기간이 소요된다고 인정하는 경우 보세공장 외 작업 허가기간은 '5년의 범위'가 아니라 '2년의 범위'이므로 ④가 틀린 진술(=정답)이다. ①(허가신청일부터 10일 이내 허가 여부 통지), ②(작업장 반입 외국물품은 지정기간 만료 시까지 보세공장에 있는 것으로 의제), ③(지정기간 경과 후 잔존 외국물품에 대해 허가받은 보세공장 운영인으로부터 관세 즉시 징수), ⑤(허가기간 종료일부터 5일 이내 작업완료 결과 통보)는 모두 옳은 진술이다.",
