        "보세작업의 '전부'를 장외작업에 의존하는 경우는 오히려 보세공장 특허 제한사유(2019 #5). '일부'를 다른 보세공장·자유무역지역에서 수행하는 것은 허가로 가능(2025 #11 정답④)",
