      "lawBasis": "관세법 제187조(보세공장 외 작업 허가): 제1항(가공무역·국내산업 진흥상 필요 시 기간·장소·물품을 정하여 보세공장 외 작업 허가), 제2항(허가신청 받은 날부터 10일 이내 허가 여부 통지), 제6항(공장외작업장에 반입된 외국물품은 지정기간 만료 시까지 보세공장에 있는 것으로 의제), 제8항(지정기간 경과 후 공장외작업장에 허가된 외국물품이나 그 제품이 있을 때에는 그 보세공장 운영인으로부터 관세 즉시 징수). 같은 법 제195조(보세건설장 외 작업)는 제2항에서 제187조를 준용한다. 보세공장 운영에 관한 고시(장외작업 허가기간 원칙 및 물품 1단위 장기소요 시 2년 범위 허가, 거대중량 등 계속장치 연장 1년 범위, 임가공계약서 등 일괄허가 1년 이내, 작업완료 결과 통보 5일 이내, 원보세공장 관할세관 관리·곤란 시 장외작업장 관할세관장에게 관리·감독 의뢰).",
      "sourceRef": "위험물산업기사가 아닌 보세사 기출 2과목(보세구역관리) 보세공장 장외작업: 2019년 17번, 2022년 4번, 2023년 21번, 2024년 24번, 2025년 11번. 데이터파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-2-2019.js(id 17)·bosesa-data-2-2022.js(id 4)·bosesa-data-2-2023.js(id 21)·bosesa-data-2-2024.js(id 24)·bosesa-data-2-2025.js(id 11). 대표문항=2024년 24번(원문 발문·선지·정답 그대로 인용, 정답 ④)."
