        "'본인·사용인의 법령 위반'은 반입정지(제178조①2호) 사유이지 취소(제178조②) 사유가 아님",
        "'1년 이내 3회 이상 반입정지처분'은 취소사유(제178조②3호), '2년 이상 반입실적 없어 설치목적 달성 곤란'도 취소사유(제178조②4호). 반면 '1년간 계속 반입·반출 실적 없거나 6개월 이상 보세작업 안 함'은 취소사유가 아님(2024년 15번 함정)",
