      "lawBasis": "관세법 제179조(특허의 효력상실 및 승계) — 제1항 효력상실 사유(운영 중단·기간 만료·해산/사망·취소), 제2항 효력상실 보고의무(운영인·상속인·청산인이 지체 없이), 제3항 사망(상속)·해산(승계법인)에 따른 승계신고(사망·해산일부터 30일 이내, 제174조제3항 요건), 제4항 사망·해산일부터 신고를 한 날까지 기간의 특허 의제, 제5항 결격사유(제175조) 해당자 승계신고 불가. ※양수(영업양수)는 제179조 승계신고 대상이 아니며 양수인은 제174조에 따라 새 특허를 받아야 함. 관세법 제182조(특허의 효력상실 시 조치 등) — 제1항 효력상실 시 운영인·상속인·승계법인은 외국물품을 지체 없이 다른 보세구역으로 반출, 제2항 외국물품의 종류·수량 등을 고려하여 6개월의 범위에서 세관장이 지정하는 기간 동안 특허보세구역으로 의제. 관세법 시행령 제192조의2(특허의 승계신고 절차 등) — 승계신고 절차 및 세관장의 신고일부터 5일 이내 결과 통보. 관세법 제175조(운영인의 결격사유) — 승계신고 결격.",
      "sourceRef": "보세사 기출 2과목(보세구역관리): 2020년 16번(대표문항)·2021년 21번·2022년 21번·2024년 16번(효력상실·승계, 승계신고 30일)·2025년 21번. 출처 파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-2-2020.js(id 16), bosesa-data-2-2024.js(id 16). 데이터 출처 kinz.kr CBT 기출."
