      "lawBasis": "관세법 제175조(운영인 결격사유)·제177조(장치기간)·제179조(특허 효력상실), 특허보세구역 운영에 관한 고시(운영인의 의무 — 장부·서류 2년 보관, 사고·직원 채용·면직·시정명령 등 지체없이 보고, 30일 이상 휴지·폐업 신고, 매년 2월말 운영상황 보고 등)",
