      "lawBasis": "관세법 제174조(특허보세구역의 설치·운영 특허), 제177조(장치기간 및 반출명령), 제178조(반입정지·취소), 관세법 시행령 제190조(업무내용 등의 변경)·제191조(수용능력 증감 등의 변경), 「특허보세구역 운영에 관한 고시」(운영인의 명의대여 금지·의무, 업무내용 변경 승인, 수용능력 증감 승인 및 준공 통보, 지체 없는 보고사항 규정)",
      "sourceRef": "보세사 기출 2과목(보세구역관리) — 2019 no.25, 2020 no.1(대표문항), 2022 no.22, 2023 no.18, 2024 no.14. 파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-2-2020.js (id 1) 외 각 연도 bosesa-data-2-<year>.js"
