      "conceptExplanation": "보세판매장(면세점) 운영인이 특허기간 만료·반납·취소 등으로 특허를 상실하면, 그 보세판매장에 남아 있는 외국물품(재고)을 처리하는 단계별 절차가 「보세판매장 운영에 관한 고시」에 정해져 있다. 흐름은 다음과 같다.\n\n① 재고조사·현품확정: 특허가 상실되면 세관장은 즉시 재고조사를 실시하여 현품을 확정한다.\n\n② 1차 처리(6개월 이내·세관장이 정한 기간): 운영인은 특허상실일부터 6개월 이내의 범위에서 세관장이 정한 기간 내에 재고물품을 ⓐ판매, ⓑ다른 보세판매장에 양도, ⓒ외국으로 반출, ⓓ수입통관절차에 의거 통관 중 하나의 방법으로 처리하여야 한다.\n\n③ 이고(移庫): 위 세관장이 정한 기간이 경과한 때에는 미처리 재고물품을 「세관장이 지정한 보세구역(지정장치장 또는 세관장이 지정한 보세구역)」으로 이고하여야 한다. 이고 장소의 지정 주체는 운영인이 아니라 세관장이라는 점이 핵심 함정이다.\n\n④ 2차 처리(이고일부터 6개월 이내): 이고한 물품은 운영인이 이고한 날부터 6개월 이내에 다른 보세판매장에 양도하거나 외국으로 반출하여야 한다.\n\n⑤ 체화처리: 이고일부터 6개월 이내에 양도·반출하지 아니한 때에는 「보세화물 장치기간 및 체화처리에 관한 고시」에 따른 체화처리(매각 등) 절차에 따라 처리한다.\n\n즉 '6개월(1차) → 세관장 지정 보세구역으로 이고 → 6개월(2차) → 체화처리'라는 두 번의 6개월 단계와 이고 주체(세관장 지정)를 정확히 구분하는 것이 출제 포인트다.",
      "trapAnalysis": "대표문항(2019년 19번)은 이고(移庫) 장소의 '지정 주체'를 바꿔치기한 함정이다. 세관장이 정한 기간이 경과하면 「세관장이 지정한 보세구역(지정장치장 등)」으로 이고하여야 하는데, 선지 ③은 이를 '운영인이 지정한 보세구역'으로 슬쩍 바꿔 틀린 설명을 만들었다. 나머지 선지(즉시 재고조사·현품확정, 6개월 이내 세관장이 정한 기간 내 판매·양도, 이고일부터 6개월 내 양도·반출, 6개월 내 미반출 시 체화처리)는 모두 옳아, 정답으로 끌려가기 쉽다.\n\n2021년 8번은 같은 개념을 빈칸형으로 출제하여 두 '6개월' 기간 숫자를 모두 묻는다. 1차 처리기간 6개월과 이고 후 처리기간 6개월을 헷갈려 2개월·3개월 등으로 유도하는 오답(가·나·다·라)을 배치했다. 두 단계 기간이 '모두 6개월'이라는 점, 그리고 이고 주체가 세관장이라는 점을 동시에 정확히 기억해야 두 유형 모두 잡을 수 있다.",
      "answerKey": "정답은 ③이다. 세관장이 정한 1차 처리기간이 경과한 때 재고물품을 이고하는 장소는 '운영인이 지정한 보세구역'이 아니라 '세관장이 지정한 보세구역(지정장치장 또는 세관장이 지정한 보세구역)'이다. 이고 장소의 지정 주체를 운영인으로 잘못 기재했으므로, '틀린 것'을 찾는 발문의 정답이다. ①(특허상실 즉시 재고조사·현품확정), ②(6개월 이내 범위에서 세관장이 정한 기간 내 판매·양도 등), ④(이고일부터 6개월 이내 양도·외국반출), ⑤(이고일부터 6개월 내 미반출 시 체화처리)는 모두 고시 규정에 부합하는 옳은 설명이다.",
