      "conceptExplanation": "「보세판매장 운영에 관한 고시」 제2조의 정의 규정을 묻는 유형이다. 핵심 용어를 정확히 암기해야 한다. ① 판매장: 판매물품을 실제로 판매하는 장소인 매장과, 계단·에스컬레이터·화장실·사무실 등 물품판매와 직접 관련이 없는 '공용시설'을 '포함한다'(★공용시설 제외 X). 즉 판매장 = 매장 + 공용시설. ② 매장: 판매물품을 실제로 진열·판매하는 장소만을 말한다(공용시설 제외). ③ 통합물류창고: 보세판매장 협의단체의 장이 회원사의 원활한 보세화물 관리와 물류지원을 위하여 보세판매장의 보관창고와 '동일한 기능'을 수행하도록 설치한 곳을 말한다(설치 주체 = 협의단체장, 기능 = 보관창고와 동일). ④ 인도장: 시내면세점 및 전자상거래로 판매한 물품을 구매자에게 인도하기 위한 곳으로 출국장 보세구역 내 설치장소, 항공화물탁송 보세구역, 외국무역선·여객선 선내, 통관우체국 내 세관통관장소, 입국장 인도장 등이다(★시내면세점 매장은 인도장 아님). ⑤ 보세판매장 협의단체: 운영인의 공정한 상거래질서를 자율적으로 확립하고 보세판매장제도의 발전을 위하여 설립된 비영리법인. ⑥ 출국장면세점: 출국장에서 출국인 및 통과여객기(선)에 의한 임시체류인에게 판매하는 보세판매장. 통합물류창고는 별도 허가를 받는 것이 아니라 협의단체장이 특허받은 보세창고 또는 자유무역지역 물류창고를 활용하는 체계라는 점(2025년 출제)도 함께 정리해야 한다.",
      "trapAnalysis": "최대 함정은 '판매장'과 '매장'의 정의를 교묘하게 뒤섞는 것이다. ②번은 '판매장'을 설명하면서 '매장만을 말하며 공용시설은 제외한다'고 서술했는데, 고시상 '판매장'은 매장에 더해 계단·에스컬레이터·사무실 등 공용시설을 '포함한다'. 즉 매장(공용시설 제외)의 정의를 판매장에 끼워넣어 '제외'로 뒤집은 전형적 반대 진술 함정이다. 출제자는 '판매장 = 매장'이라고 착각하도록 유도한다. 반드시 판매장 ⊃ 매장(판매장은 매장+공용시설, 매장은 공용시설 제외)으로 포함관계를 구분해야 한다. 또 다른 단골 함정으로 ③ 인도장에 '시내면세점 매장'을 끼워넣는 변형(2019년 출제), 통합물류창고의 설치주체를 '운영인'이나 '세관장'으로 바꾸거나 '허가를 받아야 한다'로 절차를 비트는 변형(2025년 출제)이 있다.",
      "answerKey": "정답은 ②. '판매장'은 매장뿐 아니라 계단·에스컬레이터·사무실 등 물품판매와 직접 관련 없는 공용시설을 '포함한다'. ②는 이를 '제외한다'로 정반대로 서술하여 틀렸다(공용시설을 제외하는 것은 '판매장'이 아니라 '매장'의 정의). 오답인 ①(출국장면세점), ③(인도장 — 출국장 보세구역 내 설치장소·항공화물탁송 보세구역 등), ④(보세판매장 협의단체 = 비영리법인), ⑤(통합물류창고 = 협의단체장이 보관창고와 동일 기능 수행하도록 설치)는 모두 고시 정의와 일치하는 옳은 설명이다.",
