      "lawBasis": "보세판매장 운영에 관한 고시 제2조(정의) — 판매장(매장+공용시설 포함)·매장(공용시설 제외)·인도장·통합물류창고·보세판매장 협의단체·출국장면세점 등의 정의. 관세법 제196조(보세판매장), 제196조의2(시내·입국장면세점). (참고: 내국인 보세판매장 구매한도는 2020년 당시 미화 5,000달러였으나 2022-03-18 폐지되어 현행 규정 아님 — 본 용어정의 문항과는 직접 관련 없음.)",
