        "반출입신고 범위 혼동 주의: 동일 사업장 내 기능 간 이동=신고생략 / 운영인(사업장) 상호간 이동=반출입신고 대상(보세운송신고가 아님). 외국 도착·보세운송 반입물품=House B/L 단위 반입신고",
        "보세판매장 기능 수행 종합보세구역의 '판매용 내국물품' 반출입신고를 일반적으로 생략·간소화한다고 단정하면 틀림(2024 no.5 ⑤)",
