      "lawBasis": "관세법 제197조(종합보세구역의 지정 등), 제198조(종합보세사업장의 설치·운영에 관한 신고 등), 제199조(종합보세구역에의 반입·반출 등), 제200조(반출입물품의 범위 등), 제201조(운영인의 물품관리), 제204조(종합보세구역 지정의 취소 등) 및 동법 시행령·「종합보세구역의 지정 및 운영에 관한 고시」. 장기보관화물 매각 관련 「보세화물 장치기간 및 체화처리에 관한 고시」 준용.",
