      "conceptExplanation": "지정보세구역(지정장치장·세관검사장)은 특허보세구역과 달리 '세관장이 일정 구역을 지정'하여 설정하는 보세구역이다. 핵심은 '아무 토지·건물이나 지정할 수 있는 것이 아니라, 그 소유·관리 주체가 법에서 한정된 자여야 한다'는 점이다. 관세법 제166조(지정보세구역의 지정)에 따르면 세관장은 ① 국가, ② 지방자치단체, ③ 공항시설 또는 항만시설을 관리하는 법인이 소유하거나 관리하는 토지·건물 또는 그 밖의 시설을 지정보세구역으로 지정할 수 있다. 다만 해당 토지·건물이 국가·지자체·공항만시설관리법인의 소유·관리가 아닐 때에는 그 소유자·관리자의 동의를 받아야 지정할 수 있다(세관이 소유·관리하는 토지·건물은 동의 없이 지정 가능).\n\n따라서 '주체(누구의 토지·건물인가)'가 출제의 핵심이다. 지정 가능 주체는 (가)세관(국가의 일부), (나)국가기관(예: 국토교통부 등), (다)지방자치단체(예: 인천광역시 등), (라)공항시설 관리법인(예: 인천국제공항공사 등), (마)항만시설 관리법인(예: 부산항만공사 등)으로 한정된다. 반면 '공공기관' 일반이나 '한국관광공사'처럼 공항·항만 시설을 관리하는 법인이 아닌 공공기관은 비록 공적 성격이 있어도 제166조의 지정대상 주체에 열거되어 있지 않으므로, 그 소유·관리 토지·건물은 동의를 받더라도 지정보세구역으로 지정할 수 없다. 부산항만공사는 '항만시설 관리법인'에 해당하므로 가능하지만, 한국관광공사는 관광 진흥을 목적으로 하는 공공기관일 뿐 공항·항만 시설을 관리하는 법인이 아니므로 불가능하다는 점이 함정의 핵심이다.\n\n세관검사장(제173조)은 통관하려는 물품을 검사하기 위하여 세관장이 지정하는 장소로 지정보세구역의 한 종류이며(세관청사·국제공항 휴대품검사장 등), 검사를 위한 일시 반입 장소라는 점에서 보관책임을 지는 '화물관리인'을 두는 지정장치장(제172조)과 구별된다. 즉 세관검사장에는 화물관리인을 지정하지 않는다.",
      "trapAnalysis": "함정 ①: '○○공사·○○공단처럼 공적 기관이면 다 지정대상'이라는 착각을 노린다. 같은 '공사'라도 부산항만공사는 항만시설을 관리하는 법인이므로 지정대상이지만, 한국관광공사는 공항·항만 시설 관리법인이 아니므로 지정대상이 아니다. '공사'라는 명칭이 아니라 '공항·항만 시설을 관리하는 법인인지'를 따져야 한다.\n함정 ②: '소유자의 동의를 받았다'는 문구로 적법성을 위장한다. 동의는 지정의 '절차요건'일 뿐, 애초에 주체가 제166조의 지정대상(국가·지자체·공항만시설관리법인)에 들지 않으면 동의를 받아도 지정할 수 없다. 한국관광공사 사장의 동의 문구에 현혹되면 안 된다.\n함정 ③: 2020년 문제처럼 선지에 '공공기관이 소유·관리하는 토지나 건물'을 넣어 정답으로 출제한다. '공공기관' 일반은 지정대상 주체가 아니다(국가·지자체·공항만시설관리법인만 열거).\n함정 ④(연계): 세관검사장 관련으로 '세관검사장에 화주를 갈음하여 보관책임을 지는 화물관리인을 지정하여야 한다'는 식의 선지가 자주 틀린 보기로 출제된다(2021년 15번). 화물관리인은 지정장치장 제도이고 세관검사장은 해당하지 않는다.",
      "answerKey": "정답은 ④. 한국관광공사는 관세법 제166조의 지정보세구역 지정대상 주체(국가·지방자치단체·공항시설 또는 항만시설을 관리하는 법인)에 해당하지 않으므로, 비록 한국관광공사 사장의 동의를 받더라도 그 소유·관리 토지·건물은 지정보세구역으로 지정할 수 없다.\n①(세관 소유 토지·건물) 옳음: 세관이 소유·관리하는 토지·건물은 동의 없이도 지정 가능한 대표적 지정대상이다.\n②(국토교통부=국가기관, 장관 동의) 옳음: 국가가 소유·관리하는 토지·건물로서 그 기관장 동의를 받은 경우 지정 가능하다.\n③(인천광역시=지방자치단체, 시장 동의) 옳음: 지방자치단체가 소유·관리하는 토지·건물로서 그 장 동의를 받은 경우 지정 가능하다.\n⑤(부산항만공사=항만시설 관리법인, 사장 동의) 옳음: 항만시설을 관리하는 법인이 소유·관리하는 토지·건물로서 그 법인 동의를 받은 경우 지정 가능하다.",
      "cautions": [
        "'공사'라는 명칭에 속지 말 것 — 부산항만공사·인천국제공항공사는 공항·항만 '시설 관리법인'이라 지정대상이지만, 한국관광공사는 공항·항만 시설을 관리하지 않으므로 지정대상이 아니다.",
        "'공공기관' 일반은 지정대상 주체가 아니다(2020년 14번 정답). 지정대상은 국가·지방자치단체·공항만시설관리법인으로 한정 열거되어 있다.",
        "동의(소유자·관리자 동의)는 주체요건을 충족한 뒤의 절차요건일 뿐, 동의가 있어도 주체가 부적격이면 지정 불가.",
        "세관검사장(제173조)에는 보관책임을 지는 '화물관리인'을 지정하지 않는다 — 화물관리인은 지정장치장(제172조) 제도다(2021년 15번 함정).",
        "지정보세구역=세관장이 '지정', 특허보세구역=세관장이 '특허'로 설정 주체·방식이 다르다. 지정보세구역은 지정장치장·세관검사장 2종."
      ],
      "memorize": [
        "지정보세구역 지정대상 주체 3가지: ①국가 ②지방자치단체 ③공항시설·항만시설을 관리하는 법인 (이 3가지만!)",
        "제외(불가): 공공기관 일반, 한국관광공사(공항·항만 시설 관리법인 아님)",
        "세관 소유·관리 토지·건물 → 동의 불요 / 그 외(국가·지자체·공항만시설관리법인) → 소유자·관리자 동의 필요",
        "지정보세구역 = 지정장치장 + 세관검사장 (2종)",
        "세관검사장: 화물관리인 지정 X (화물관리인은 지정장치장)",
        "근거: 관세법 제166조(지정보세구역의 지정), 제173조(세관검사장)"
      ],
      "lawBasis": "관세법 제166조(지정보세구역의 지정) — 세관장은 국가, 지방자치단체, 공항시설 또는 항만시설을 관리하는 법인이 소유하거나 관리하는 토지·건물 또는 그 밖의 시설을 지정보세구역으로 지정할 수 있으며, 그 소유자·관리자가 아닌 경우 소유자·관리자의 동의를 받아야 한다. 관세법 제169조(지정장치장)·제173조(세관검사장) — 지정보세구역의 종류. 관세법 제172조(물품에 대한 보관책임·화물관리인) — 화물관리인 지정은 지정장치장에 관한 제도.",
      "sourceRef": "위험물… (보세사 자격시험) 2과목 보세구역관리 — 2020년 14번, 2021년 15번, 2022년 15번. 파일: C:\\Users\\pkm77\\Desktop\\home-desktop project\\project-dashboard\\claude\\previews\\tradelogix-nexus\\bosesa-data-2-2020.js (id 14), bosesa-data-2-2021.js (id 15), bosesa-data-2-2022.js (id 15). 대표문항은 2022년 15번(한국관광공사 함정 포함)."
