      "lawBasis": "관세법 제185조(보세공장)·제5항(수입을 목적으로 하는 물품을 제조·가공하는 것을 목적으로 하는 업종 제한 — 기획재정부령으로 정하는 바에 따라), 제185조 제2항(내국물품만을 원료·재료로 하거나 내국물품+외국물품을 함께 원료·재료로 하여 제조·가공 시 세관장 허가); 보세공장 운영에 관한 고시 제8조(특허의 제한 — 제2항 임의적 제한사유: 보수작업만·폐기물·손모율 불안정 농수축산물·전부 장외작업, 제1항 절대적 제한·관계행정기관 미허가자 등), 제5조(특허요건)·제6조(설치·운영의 특허, 제출서류); 관세법 제175조(운영인 결격사유, 비교 개념)",
