      "lawBasis": "「보세공장 운영에 관한 고시」(관세청 고시) — 보세공장 반입 원재료의 '원상태 국외반출' 허용 규정. 상위 근거: 관세법 제185조(보세공장)·제186조(사용신고 등)·제187조(보세공장 외 작업 허가). 관련 비교: 관세법 제188조(제품과세)·제189조(원료과세).",
