      "conceptExplanation": "보세공장 운영에 관한 고시상 「잉여물품」이란 보세작업으로 인하여 발생하는 부산물과 불량품, 제품생산중단 등의 사유로 사용하지 않는 원재료와 제품 등을 말하며, 보세공장에서 제조·가공한 물품에 전용되는 포장·운반용품도 잉여물품의 범위에 포함된다. (1) 관리대장: 운영인은 잉여물품이 발생한 때에는 잉여물품 관리대장에 잉여물품의 형태, 품명·규격, 수량(또는 중량), 발생사유를 기록·유지하여야 한다. (2) 처리방법: 잉여물품은 수출, 다른 보세공장 등으로의 양수도, 수입신고, 폐기 등의 방법으로 처리할 수 있으며, 반드시 수입신고 수리 후에만 반출하는 것은 아니다. (3) 폐기: 잉여물품을 폐기하려는 운영인은 미리 세관장의 승인을 받아야 한다. 다만 세관장은 성실하다고 인정하는 업체(수출입 안전관리 우수업체 포함) 중 멸각 후의 잔존물에 실질적 가치가 「없는」 물품에 대하여는 업체의 신청을 받아 사전에 자체폐기 대상물품으로 지정할 수 있다. 폐기를 완료한 운영인은 관련 자료를 첨부하여 폐기완료일부터 30일 이내에 세관장에게 폐기완료보고를 하여야 한다. (4) 잔존물 과세: 폐기(멸각) 후의 잔존물에 실질적 가치가 있는 때에는 폐기 후의 물품의 성질과 수량에 따라 관세 등을 납부하여야 한다. (5) 수입신고전 반출: 운영인이 잉여물품을 수입신고 전에 즉시 반출하려는 경우에는 「보세공장 잉여물품 수입신고전 반출신고서」를 세관장에게 제출해야 하며, 수입신고전 반출한 잉여물품은 반출신고서를 제출한 날부터 「10일 이내」에 반출신고서 건별로 수입신고하여야 한다.",
      "trapAnalysis": "이 유형의 핵심 함정은 잉여물품의 「범위」다. 보세공장에서 제조·가공한 물품에 전용되는 포장·운반용품도 잉여물품에 포함되는데(2019-18 ②), 이를 「포함되지 아니한다」로 뒤집어 오답을 만든다. 같은 범위 함정은 2022-1 ①에서 「세트를 구성하거나 함께 거래되는 물품을 포함한다」처럼 정의에 없는 내용을 덧붙이는 방식으로도 등장한다. 두 번째 함정은 자체폐기 대상 지정 요건의 「가치 유무」 방향 뒤집기다 — 자체폐기 사전지정은 멸각 후 잔존물에 실질적 가치가 「없는」 물품이 대상인데, 「가치가 있는 물품」으로 거꾸로 서술하여 오답을 만든다(2022-1 ④). 세 번째는 기한·숫자 함정으로, 수입신고전 반출 잉여물품의 수입신고 기한 「10일」을 「30일」로 바꾸거나(2023-20 ⑤), 폐기완료보고 기한 「30일」을 다른 숫자로 바꾼다. 또한 「잔존물에 가치가 있으면 폐기 후의 성질·수량에 따라 과세」 vs 「가치가 없으면 과세하지 않음」을 혼동하게 만든다.",
