      "conceptExplanation": "보세공장의 「원재료」는 관세법 시행령 제199조 제1항 및 보세공장 운영에 관한 고시상 ①당해 보세공장에서 생산하는 제품에 물리적 또는 화학적으로 결합되는 물품, ②제품을 제조·가공하거나 이와 비슷한 공정에 투입되어 소모되는 물품, ③제품의 수리·조립·검사·포장 및 이와 비슷한 작업에 직접적으로 투입되어 소모되는 물품으로 한정된다. 즉 「제품과의 직접적 관련성(결합 또는 직접 투입·소모)」이 핵심 표지이다. 또한 시행령 제199조 제2항상 원재료는 당해 보세공장에서 생산하는 제품에 소요되는 수량을 「객관적으로 계산할 수 있는 물품」이어야 한다(소요량 객관 계산 가능성). 반대로 기계·기구 등의 작동 및 유지를 위한 연료·윤활유 등 「제품의 생산·수리·조립·검사·포장 등 작업에 간접적으로 투입되어 소모되는 물품」은 시행령 제199조 제1항 단서로 명시적으로 제외된다. 한편 「연구·개발에 투입되는 물품」은 위 세 가지 원재료 항목(제품 생산 소요분)에 애초에 포섭되지 않아 원재료의 범위에 해당하지 않는다(연구·시험용은 제품 생산용 원재료가 아니라는 취지). 출제는 (가) '간접 소모 물품(연료·윤활유)도 원재료에 해당한다'고 포함시키는 오답형, (나) '연구·개발 직접투입 물품'을 직접투입 항목들 사이에 끼워 넣어 원재료에 해당하는 것처럼 위장하는 오답형, (다) 원재료 정의에 '제품과 세트를 구성하거나 함께 거래되는 물품' 등 잉여물품·반입대상 개념을 섞어 넣는 변형으로 반복된다.",
      "trapAnalysis": "함정의 핵심은 「직접」과 「간접」의 한 글자 차이다. 선지 ①②④는 모두 '결합' 또는 '직접적으로 투입·소모'라는 표지로 원재료에 해당하는 옳은 설명이고, ⑤는 '소요량을 객관적으로 계산할 수 있어야 한다'는 별도 요건으로 역시 옳다. 정답 ③만이 '연료·윤활유 등 ……간접적으로 투입되어 소모되는 물품'을 원재료에 「해당된다」고 적어 놓았는데, 이들은 명백히 원재료에서 「제외」되는 대표 사례다. 수험생이 '연료·윤활유'라는 낯익은 단어와 '소모되는 물품'이라는 표현만 보고 무심코 옳다고 넘기도록 설계된 전형적 함정이다. 2025년 17번은 같은 개념을 뒤집어, '연구·개발에 직접적으로 투입되는 물품'을 '물리적 결합·화학적 결합·수리조립 직접투입·제조가공 직접소모'라는 진짜 원재료 항목들 사이에 끼워 넣고 「원재료에 해당하지 않는 것」을 고르게 하여, 직접투입이라는 부사어에 속아 정답(연구개발용)을 놓치도록 유도한다. 즉 같은 개념이라도 묻는 방식('틀린 것' vs '해당하지 않는 것')과 제외 대상('연료·윤활유' vs '연구·개발')이 해마다 바뀌므로 키워드 암기가 아니라 '직접/간접' '제품 생산 소요/연구개발'이라는 판단 기준을 잡아야 한다.",
      "answerKey": "정답은 ③이다. ③은 연료·윤활유 등 기계·기구의 작동·유지를 위해 「간접적으로」 투입·소모되는 물품을 원재료에 해당한다고 했으나, 이러한 간접 소모 물품은 원재료 범위에서 제외되므로 틀린 설명이다(정답). 오답인 ①은 제품에 물리적·화학적으로 결합되는 물품으로 원재료에 해당(옳음), ②는 제조·가공 공정에 투입·소모되는 물품으로 원재료에 해당(옳음), ④는 수리·조립·검사·포장 작업에 직접 투입되는 물품으로 원재료에 해당(옳음), ⑤는 제품 소요량을 객관적으로 계산할 수 있어야 한다는 원재료 요건과 일치(옳음)하여 모두 '틀린 것'을 묻는 발문의 정답이 아니다.",
