      "lawBasis": "관세법 시행령 제199조(보세공장원재료의 범위 등): 제1항은 보세공장 원재료를 ①당해 보세공장에서 생산하는 제품에 물리적·화학적으로 결합되는 물품, ②제품을 제조·가공하거나 이와 비슷한 공정에 투입되어 소모되는 물품, ③제품의 수리·조립·검사·포장 및 이와 비슷한 작업에 직접적으로 투입되어 소모되는 물품으로 한정한다. 다만 같은 항 단서로 기계·기구 등의 작동 및 유지를 위한 연료·윤활유 등 제품의 생산·수리·조립·검사·포장 및 이와 비슷한 작업에 「간접적으로」 투입되어 소모되는 물품은 원재료에서 제외한다(연료·윤활유 제외는 명문 단서). 제2항은 원재료가 당해 보세공장에서 생산하는 제품에 소요되는 수량을 객관적으로 계산할 수 있는 물품이어야 함을 정한다. 한편 '연구·개발에 투입되는 물품'은 시행령 제199조에 별도 제외 항목으로 열거된 것이 아니라, 제품 생산에 소요되는 원재료(제1항 각 호)에 처음부터 포섭되지 않아 원재료의 범위에 해당하지 않는 것이다(연구·시험용 물품 취지). 관련: 관세법 제185조(보세공장), 보세공장 운영에 관한 고시.",
