      "conceptExplanation": "보세구역 장치의 총칙(관세법 제155조~제157조의2)을 묶은 빈출 영역이다. ① 장치의무(제155조): 외국물품과 내국운송 신고를 하려는 내국물품은 원칙적으로 보세구역이 아닌 장소에 장치할 수 없다(보세구역 장치 강제). 다만 ㉠수출신고가 수리된 물품, ㉡크기·무게의 과다 등으로 보세구역에 장치하기 곤란하거나 부적당한 물품, ㉢재해 등 부득이한 사유로 임시 장치한 물품, ㉣검역물품, ㉤압수물품, ㉥우편물 등은 보세구역이 아닌 곳에도 장치할 수 있는 예외다. ② 반출입신고(제157조): 보세구역에 물품을 반입·반출하려는 자는 대통령령으로 정하는 바에 따라 세관장에게 신고하여야 하고, 세관공무원은 반입·반출 물품을 검사할 수 있으며, 세관장은 보세구역에 반입할 물품의 종류를 제한할 수 있다. ③ 반출기한(제157조의2): 관세청장이 정하는 보세구역(주로 컨테이너전용 보세창고 등 신속통관 대상)에 반입되어 수입신고가 수리된 물품의 화주(또는 반입자)는 장치기간에도 불구하고 그 수입신고 수리일부터 15일 이내에 해당 물품을 보세구역으로부터 반출하여야 한다(반출의무·체화방지 취지). 이 15일의 반출기간은 그 물품을 보세구역에서 반출하는 것이 보세구역의 외국물품 장치에 방해가 되지 아니하는 경우로서 '세관장의 승인'을 받았을 때에만 연장된다(승인이 없으면 자동 연장되지 않음). 즉 ②반출입은 '신고', ③반출기한 연장은 '세관장의 승인'이라는 행정행위 구분이 핵심이다.",
      "trapAnalysis": "최대 함정은 ⑤번이다. '외국물품 장치에 방해가 되지 않는 경우'라는 그럴듯한 조건절을 제시해 마치 그 조건만 충족하면 반출기한이 자동으로 연장되는 것처럼 착시를 일으킨다. 그러나 그 조건은 '세관장이 연장을 승인할 수 있는 요건'일 뿐이고, 실제 연장의 효력은 반드시 '세관장의 승인'이라는 행정행위가 있어야 발생한다. 조건 충족=자동연장으로 단정하는 순간 오답이다. 또 다른 단골 함정은 숫자·기준시점 변형이다. 15일을 '7일·10일·30일'로, 기준시점인 '수입신고 수리일'을 '반입일·수입신고일'로 바꿔 출제한다(④는 둘 다 정확하므로 옳음). 반출입을 '승인' 대상인 것처럼, 반대로 반출기한 연장을 '신고'로 충분한 것처럼 신고/승인을 뒤바꾸는 변형도 빈출이다(① 반출입=신고, ⑤ 연장=승인이 정답 키워드).",
      "answerKey": "정답은 ⑤번이다. 관세법 제157조의2의 15일 반출기간은 '외국물품 장치에 방해가 되지 아니하는 경우로서 세관장의 승인을 받은 때'에 한하여 연장되므로, '승인을 받지 않아도 연장된다'는 ⑤는 규정과 정면으로 배치되어 틀린 설명(=정답)이다. 나머지는 모두 옳다. ①은 제157조의 반출입 신고의무, ②는 세관공무원의 반입·반출 물품 검사권, ③은 세관장의 반입물품 종류 제한권으로 모두 규정에 부합한다. ④는 관세청장이 정하는 보세구역의 수입신고 수리물품은 장치기간에도 불구하고 수입신고 수리일부터 15일 이내 반출하여야 한다는 의무를 기준시점·기한 모두 정확히 기술하여 옳다.",
