        "반출기한 15일의 기준시점은 '수입신고 수리일'이다. '반입일'이나 '수입신고일(수리 전)'로 바꾼 선지는 오답.",
        "15일 반출의무는 '관세청장이 정하는 보세구역'에 한정된다. 모든 보세구역에 일률 적용된다고 단정하면 안 된다('장치기간에도 불구하고'가 단서).",
        "장치의무(제155조)의 예외(수출신고 수리물품, 검역물품, 압수물품, 우편물, 거대·중량물 등)는 '보세구역에 장치하여야 하는 물품/장치할 수 없는 물품'을 묻는 문제(2022 18번)와 직결되니 함께 암기.",
        "반출기간 연장요건인 '외국물품 장치에 방해가 되지 않을 것'은 연장 가능 조건일 뿐 자동연장 사유가 아님(반드시 승인 필요)."
