      "lawBasis": "관세법 제155조(물품의 장치), 제156조(보세구역 외 장치의 허가), 제157조(물품의 반입·반출), 제157조의2(수입신고수리물품의 반출), 관세법 시행령 제176조(물품의 반출입신고)",
      "sourceRef": "보세사 기출 2과목(보세구역관리) 2020년 3번(대표문항)·2022년 18번(보세구역 장치 대상·압수물품 예외)·2024년 12번(보세구역 총칙 A~E 종합) / bosesa-data-2-2020.js, bosesa-data-2-2022.js, bosesa-data-2-2024.js"
