      "conceptExplanation": "보세창고(특허보세구역) 운영의 실무 영역은 「특허보세구역 운영에 관한 고시」와 「보세화물관리에 관한 고시」가 핵심 근거다. 시험에서는 ①보세사 채용·운영 의무, ②특허신청 시 제출하는 내부화물관리규정의 포함사항, ③장치물품에 이상이 있을 때의 물품이상신고서 기재사항이 반복 출제된다.\n\n[1] 보세사 운영 의무: 운영인은 보세구역 화물관리를 위해 보세사를 채용하여 상주시켜야 하며, 보세사가 퇴사·업무정지 등으로 업무를 수행할 수 없게 된 경우 '2개월 이내'에 다른 보세사를 채용해 업무를 수행하게 해야 한다(3개월이 아님에 주의).\n\n[2] 내부화물관리규정의 포함사항: 영업용 보세창고 특허신청인이 세관장에게 제출하는 내부화물관리규정에는 ▲내부 화물관리 종합책임자 및 책임체계 ▲화물 반출입 및 보관 절차 ▲출입자 통제 및 시설안전관리 ▲세관 보고 사항 및 절차 ▲대장 기록 체계 ▲내부고발자 포상과 청렴위반자 징계 체계 등이 포함된다. 반면 '보세화물 취급 직원(근무 직원)의 채용 조건 및 절차'는 화물관리규정의 법정 포함사항이 아니다(화물관리 내용과 무관한 인사 사항이므로 제외).\n\n[3] 물품이상신고: 보세구역에 장치된 물품에 이상(부족·과다·손상 등)이 있는 경우 운영인은 세관장에게 '물품이상신고서'를 제출해야 한다. 이상신고서 기재사항은 ▲해당 물품의 품명·규격·수량 및 가격 ▲포장의 종류·번호 및 개수 ▲장치장소 및 장치사유 ▲발견연월일, 이상의 원인 및 상태 등이다. '장치하는 물품의 종류·번호 및 수용능력'은 특허 신청서류 등에 기재하는 사항으로 이상신고서 기재사항이 아니다.\n\n이 세 가지는 모두 '운영인이 보세창고를 적법하게 관리·운영하기 위한 절차·서류·인력' 의무라는 점에서 한 묶음으로 이해하면 좋다.",
      "trapAnalysis": "함정의 핵심은 ④ '장치하는 물품의 종류·번호 및 수용능력'이다. 모든 선지가 보세화물 관련 서류에 등장할 법한 항목으로 구성돼 있어 익숙함만으로 정답처럼 보이게 만든다. 특히 '수용능력'은 특허보세구역 수용능력 증감(승인 사항)·특허신청서 기재사항으로 자주 출제되는 표현이라, 출제자는 이를 '이상신고서'에 슬쩍 끼워 넣어 서류 종류를 혼동하게 유도한다. 이상신고서는 '이미 장치된 개별 물품에 발생한 이상'을 보고하는 서식이므로, 물품의 품명·수량·가격·포장·장치장소·이상의 원인/상태처럼 '그 물품과 이상 자체'에 관한 정보를 적는다. 반면 '수용능력'은 시설(창고)의 보관 능력을 나타내는 개념으로 개별 물품 이상보고와 무관하다. 발문이 '아닌 것'을 묻는 부정형이라는 점도 함정 — 옳은 항목 4개를 정답으로 고르지 않도록 주의해야 한다.",
