      "conceptExplanation": "보세판매장은 외국으로 반출하거나 외교관용 등 면세물품을 판매하는 특허보세구역으로, 관세법 제196조(보세판매장)에 근거하여 세관장이 특허한다. 종류는 ①출국장면세점(출국장 보세구역 내, 출국하는 자에게 판매) ②입국장면세점(공항·항만 등 입국경로에 설치, 외국에서 국내로 입국하는 자에게 판매. 관세법 제196조 제2항에 근거하여 2019년 신설) ③시내면세점(시내에 설치, 판매물품은 판매장에서 인도하지 않고 보세운송 후 출국장 등 인도장에서 인도. 외국인 여행자에 대한 현장 인도는 관세법 제196조의2 「시내보세판매장의 현장 인도 특례」에 따름) ④외교관면세점(우리나라에 주재하는 대사 등 외교관에게 해당 물품을 사용할 것을 조건으로 판매)으로 구분된다. 네 종류 모두 관세법 제196조에 근거한 특허보세구역이라는 점이 핵심이다. 이와 구별해야 할 함정이 '지정면세점'으로, 이는 관세법상 보세판매장이 아니라 조세특례제한법에 근거하여 제주도 등 특정지역 내국인을 대상으로 운영되는 별도 면세점이다(2021년 출제). 설치지역과 관련하여, 외교관면세점은 '서울특별시·부산광역시 내에 한하여' 같은 지역 제한이 없다(2025년 ④가 근거 없는 지역제한으로 오답). 구매·통합한도(2025년 기준)는 ⓐ출국 내국인에 대한 출국장 보세판매장 판매한도는 폐지되어 한도 제한이 없고(과거 미화 5,000달러였으나 폐지), ⓑ입국장 보세판매장의 기본 판매한도는 미화 800달러이며, 이와 별도의 면세품목으로 술 2병(합계 2L 이하·미화 400달러 이하), 담배 궐련 200개비, 향수 100mL까지 판매할 수 있다. 입국장 보세판매장과 입국장 인도장이 동일 입국경로에 함께 설치된 경우 입국 시 구매한도(800달러)는 통합 적용되며 각각 별도 한도(각 800달러)를 인정하지 않는다.",
      "trapAnalysis": "'지정면세점'은 명칭에 '면세점'이 들어가고 관세법상 보세판매장과 동일하게 면세물품을 취급하기 때문에 같은 부류로 착각하기 쉽다. 그러나 지정면세점은 조세특례제한법에 근거하여 제주도 등 특정지역 내국인을 대상으로 설치·운영되는 별도 제도이므로 '관세법에 근거하여 특허한 보세구역'이 아니다. 나머지 네 선지(입국장·외교관·시내·출국장 면세점)는 모두 관세법 제196조(입국장면세점은 제196조 제2항)에 근거한 보세판매장 유형으로, '~면세점'이라는 같은 어미에 묻혀 차이를 못 보면 오답을 고르게 된다. 또한 2025년 기출처럼 '외교관면세점은 서울·부산 내에 한하여 특허받을 수 있다'는 식의 근거 없는 지역 제한, '입국장 한도 600달러'(실제 800달러), '출국 내국인 5,000달러 한도'(현재 폐지) 같이 수치·지역을 살짝 비틀어 오답을 만드는 패턴이 반복된다.",
      "answerKey": "정답은 ②(지정면세점)이다. 지정면세점은 관세법상 특허보세구역(보세판매장)이 아니라 조세특례제한법에 근거한 제주도 등 특정지역 내국인 대상 면세점이므로 '관세법에 근거하여 특허한 보세구역'에 해당하지 않는다. ①입국장면세점(관세법 제196조 제2항), ③외교관면세점, ④시내면세점, ⑤출국장면세점(이상 관세법 제196조 보세판매장)은 모두 관세법에 근거하여 세관장이 특허한 보세판매장이므로 '아닌 것'에 해당하지 않는다.",
