      "conceptExplanation": "보세공장 물품의 반출입은 「보세공장 운영에 관한 고시」가 규율한다. 핵심 쟁점은 ① 신고 갈음(생략) 관계와 ② 보세공장 반입대상 물품의 범위다.\n\n[1] 반입신고와 보세운송 도착보고의 갈음 방향(가장 빈출하는 함정)\n- 보세운송절차에 따라 보세공장에 반입되는 물품은 「반입신고」로 「보세운송 도착보고」를 갈음(겸함)한다. 즉 반입신고를 하면 별도의 도착보고가 필요 없다.\n- 시험에서는 이 방향을 거꾸로 뒤집어 \"보세운송 도착보고로 반입신고를 갈음한다\"라고 출제한다(2022-3 ①은 방향을 뒤집어 오답). 갈음하는 쪽(주체)은 「반입신고」이고, 갈음되는(생략되는) 쪽은 「보세운송 도착보고」임을 반드시 기억한다.\n- 같은 논리가 보세판매장에도 그대로 적용된다(2024-2 ④: 보세운송 도착물품을 보관창고에 반입하며 하는 전자문서 반입신고가 보세운송 도착보고를 겸하므로 \"도착보고를 별도로 해야 한다\"는 틀림).\n\n[2] 환급대상물품 반입신고의 갈음\n- 환급대상물품(수출용원재료 등)의 「반입신고」는 「보세사에 의한 반입명세의 기록」으로 갈음한다. 즉 보세사가 반입명세를 기록하면 별도 반입신고를 하지 않는다(2022-3 ② 정답).\n- 한편 「국내 수입용」 물품의 제조·가공에 필요한 내국물품 원재료에는 환급대상물품반입확인서를 발급하지 아니한다(환급은 수출용 원재료를 전제로 하므로). 또한 내국물품인 원재료의 반출입은 그 신고를 생략하게 할 수 있다(2022-3 ④는 \"신고하여야 한다\"고 단정하여 오답).\n\n[3] 보세공장 반입대상 물품의 범위\n- 반입대상에 해당하는 것: 보세공장에서 제조되어 반출된 제품의 하자보수용 물품, 수리되기 위해 반입되는 선박에 적재된 연료, 제조·가공한 물품과 세트를 구성하거나 함께 거래되는 물품, 제조·가공한 물품에 전용되는 포장·운반용품 등.\n- 반입대상에서 제외되는 것: 보세공장에서 건조·수리되는 선박에 적재하려는 선박용품 중 「환급대상물품」은 보세공장 반입대상이 아니다(일반 수출통관·환급 절차로 처리). 2025-9의 정답(②)이 바로 이 점이다.\n\n정리하면, '신고 갈음'은 (가) 보세운송 반입물품→반입신고가 도착보고 갈음, (나) 환급대상물품→보세사 반입명세 기록이 반입신고 갈음의 두 축으로 구성되고, '반입대상'에서는 환급대상 선박용품 제외가 핵심 포인트다.",
      "trapAnalysis": "① 갈음 방향 뒤집기: \"보세운송 도착보고로 반입신고를 갈음한다\"는 가장 흔한 함정이다. 실제로는 「반입신고」가 「보세운송 도착보고」를 갈음한다(주체/객체가 정반대). 갈음하는 쪽이 무엇인지(반입신고 vs 도착보고)를 묻는 방향을 항상 먼저 확인하라.\n③ '~후에만'·'~만' 단정형 함정: 잉여물품은 수출·양수도·폐기 등 여러 방법으로 처리할 수 있는데 \"수입신고 수리 후에만 반출할 수 있다\"고 한정해 오답을 만든다.\n④ 생략 가능 사항을 의무로 둔갑: 내국물품인 원재료의 반출입은 신고를 생략하게 할 수 있는 사항인데 \"세관장에게 반출입신고를 하여야 한다\"로 단정해 오답.\n⑤ 부정문 함정: 보세공장 반입 원재료는 보세운송절차에 따라 다른 보세공장으로 반출할 수 있는데 \"반출할 수 없다\"고 부정해 오답.\n[연계 함정] 2025-9는 반입대상에 「환급대상 선박용품」을 끼워 넣어 오답을 유도한다(환급대상물품은 반입대상 제외). 2024-2 ④는 전자문서 반입신고가 도착보고를 겸하는데 \"도착보고를 별도로 해야 한다\"고 함정을 판다.",
      "answerKey": "정답은 ②. 환급대상물품의 반입신고는 보세사에 의한 반입명세의 기록으로 갈음한다(보세공장 운영 고시). [오답] ① 갈음 방향이 반대다. 보세운송 반입물품은 「반입신고」로 「보세운송 도착보고」를 갈음한다. ③ 잉여물품은 수입신고 수리 후에만 반출하는 것이 아니라 수출·양수도·폐기 등으로도 처리 가능하다. ④ 내국물품인 원재료 반출입은 신고를 생략하게 할 수 있어 일률적 반출입신고 의무가 아니다. ⑤ 다른 보세공장의 원재료로 쓰기 위해 보세운송절차로 다른 보세공장에 반출할 수 있다.",
