      "conceptExplanation": "보세구역 장치물품에 대한 「보수작업」과 「해체·절단 등의 작업」은 외국물품의 성질·형상을 변경하는 행위를 일정 범위에서 허용하되, 그 한계와 절차를 엄격히 규율하는 제도다. 두 작업의 공통·차이를 정확히 구분해 외워야 한다.\n\n【1. 보수작업(관세법 제158조)】 ① 절차: 보수작업을 하려는 자는 「세관장의 승인」을 받아야 한다. 세관장은 신청을 받은 날부터 「10일 이내」에 승인 여부를 신청인에게 통지하여야 한다. ② 장소: 원칙은 보세구역 내 작업이나, 보세구역에서의 보수작업이 곤란하다고 세관장이 인정할 때에는 「보세구역 밖」에서도 보수작업을 할 수 있다(보세구역외 보수작업 승인). ③ 작업 범위: 물품의 보존을 위해 필요한 작업, 물품의 상품성 향상을 위한 개수(포장 개선·라벨표시·간단한 손질) 등 「물품의 동일성(현상·성질)을 유지하는 범위」의 작업만 가능하다. 이때 「HS상 품목분류의 변화를 가져오는 작업(제조·가공에 해당)은 보수작업으로 인정되지 않는다」(2025년 출제 함정). ④ 보수재료의 제한: 「외국물품은 수입될 물품의 보수작업의 재료로 사용할 수 없다」(제158조 제6항). ⑤ 부가물품의 지위: 보수작업으로 외국물품에 부가된 내국물품은 「외국물품으로 본다」.\n\n【2. 해체·절단 등의 작업(관세법 제159조)】 ① 절차: 해체·절단 등의 작업을 하려는 자는 「세관장의 허가」를 받아야 한다(보수작업의 '승인'과 구별). 세관장은 신청을 받은 날부터 「10일 이내」에 허가 여부를 통지하여야 한다. ② 작업 가능 물품의 종류: 「관세청장」이 정한다(세관장이 아님). ③ 작업 명령권: 세관장은 수입신고한 물품에 대하여 필요하다고 인정될 때에는 「화주 또는 그 위임을 받은 자」에게 해체·절단 등의 작업을 명할 수 있다.\n\n핵심 비교: 보수작업=「승인」/해체절단=「허가」, 둘 다 통지기간 「10일」, 작업 가능 물품 종류는 해체·절단의 경우 「관세청장」이 정함.",
      "trapAnalysis": "이 유형의 핵심 함정은 '긍정↔부정 뒤집기'와 '용어·주체 바꿔치기'다. ① 보수재료 함정(2019 대표문항): 외국물품은 수입될 물품의 보수작업 재료로 「사용할 수 없다」가 정답인데, 선지를 「사용할 수 있다」로 뒤집어 옳은 것처럼 위장한다. 이것이 가장 빈출되는 함정이다. ② 절차명 혼동(2020): 보수작업은 「승인」, 해체·절단은 「허가」로 절차 명칭이 다르다. 2020년 해체·절단 문제에서 선지를 '세관장에게 신고하여야 한다'(→ 실제는 허가)로 바꿔 오답을 만들었다. ③ 통지기간 숫자 바꾸기(2020): '7일'로 적으면 오답(정답은 10일). ④ 작업 가능 물품 종류 결정 주체(2020): '세관장이 정한다'는 오답(정답은 관세청장). ⑤ 작업범위 함정(2025): 'HS상 품목분류의 변환을 가져오는 작업도 보수작업으로 인정된다'는 오답 — 품목분류 변환은 제조·가공이므로 보수작업이 아니다. ⑥ 보세공장 특허 제한사유(2019·2020 연계): 'HS 품목분류 변화를 가져오는 조립작업'은 정상적 보세가공이라 제한사유가 아니지만, 단순 보수작업(라벨표시·용기변경·단순조립)만을 목적으로 하는 경우는 제한사유가 된다.",
      "answerKey": "정답은 ②. 관세법 제158조 제6항에 따라 「외국물품은 수입될 물품의 보수작업의 재료로 사용할 수 없다」. 선지 ②는 '사용할 수 있다'고 하여 규정과 정반대로 기재했으므로 틀린 설명이고, '틀린 것'을 묻는 발문의 정답이다. 나머지는 모두 옳다 — ① 보수작업은 세관장의 승인 대상이다. ③ 보수작업으로 외국물품에 부가된 내국물품은 외국물품으로 본다. ④ 세관장은 신청일부터 10일 이내에 승인 여부를 통지하여야 한다. ⑤ 보세구역 내 작업이 곤란하다고 세관장이 인정하면 보세구역 밖에서도 보수작업을 할 수 있다.",
      "cautions": [
        "보수작업='승인' / 해체·절단='허가' — 절차 명칭이 다르다. 둘을 바꿔 출제하는 함정 주의(2020 해체절단 문제는 '신고'로 오답 유도).",
        "'외국물품을 수입될 물품의 보수작업 재료로 쓸 수 있다'는 항상 오답 — 사용 '불가'가 원칙(제158조 제6항).",
        "HS상 품목분류 변화를 가져오는 작업은 보수작업이 아니다(제조·가공). 그러나 보세공장 특허 제한사유에서는 'HS 품목분류 변화를 가져오는 조립작업'은 정상 보세가공이라 '제한사유가 아님' — 맥락에 따라 정반대 결론이므로 혼동 금지.",
        "해체·절단 작업의 '작업 가능 물품 종류'는 세관장이 아니라 관세청장이 정한다.",
        "해체·절단 작업 명령의 상대방은 '화주 또는 그 위임을 받은 자'(운영인 아님)."
      ],
