        "승인·허가 여부 통지기간 = 모두 신청일부터 10일 이내",
        "외국물품 → 수입될 물품의 보수작업 재료로 사용 불가(제158조 ⑥)",
        "보수작업으로 외국물품에 부가된 내국물품 = 외국물품으로 봄",
        "해체·절단 가능 물품의 종류 = 관세청장이 정함",
        "보수작업은 HS 품목분류 변화 불가(변화 시 제조·가공)",
