      "lawBasis": "관세법 제158조(보수작업) — 제1항 세관장 승인, 통지 10일 이내, 제6항 외국물품의 보수재료 사용 금지, 부가 내국물품의 외국물품 의제, 보세구역 외 보수작업 / 관세법 제159조(해체·절단 등의 작업) — 세관장 허가, 통지 10일 이내, 작업 가능 물품 종류는 관세청장이 정함, 세관장의 작업명령(화주 또는 그 위임을 받은 자) / 보세공장운영에관한고시(보수작업·HS 품목분류 변환 관련 제한)",
      "sourceRef": "보세사 기출 2과목(보세구역관리) 2019년 21번(대표문항)·2020년 19번·2025년 11번. 데이터: bosesa-data-2-2019.js(id 21), bosesa-data-2-2020.js(id 19), bosesa-data-2-2025.js(id 11). 출처 kinz.kr, Claude 법령 근거 해설 재작성본."
