      "lawBasis": "관세법 제175조(운영인의 결격사유) — 특히 제7호('제268조의2·제269조·제270조·제270조의2·제271조·제274조·제275조의2·제275조의3·제275조의4'에 따른 벌금형·통고처분 후 2년 미경과, 다만 제279조 처벌자 제외) 및 제6호(특허취소·제276조제3항제3호의2 등), 제177조의2(특허보세구역 운영인의 명의대여 금지), 제275조의3(명의대여행위죄 — 명의대여 위반의 벌칙으로 제175조 제7호와 연결), 제279조(양벌규정 — 결격 제외)",
