        "결격사유 조문(법 제175조)은 ①특허요건(소극적 요건) ②사후 결격 시 특허취소 사유(제178조제2항) ③승계신고 제한사유(제179조)에 모두 연결됨 — 한 군데로만 외우지 말 것",
        "자본금 2억원 등 자본금·재산 요건은 일부 시설유형의 요건일 뿐, 모든 신청인의 공통 결격·특허요건이 아님",
        "신청인이 보세사 자격을 직접 취득하면 별도 보세사 채용 의무 없음(자격취득 OR 보세사 채용)",
        "해산·사망은 결격사유가 아니라 특허 '효력상실' 사유(제179조)임 — 취소·결격과 혼동 금지"
