      "lawBasis": "관세법 제175조(운영인의 결격사유: 파산 미복권, 징역형 실형 집행종료·면제 후 2년 미경과, 집행유예 기간 중, 벌금·통고처분 후 2년 미경과 등), 제178조제2항(특허취소 — 결격사유 해당 시 등), 제179조(특허 효력상실 및 승계 — 해산·사망 등 효력상실, 결격자 승계신고 제한), 특허보세구역 운영에 관한 고시(신청인 요건 — 체납액 없을 것, 보세사 자격취득 또는 채용, 위험물품 취급 시 관계기관 허가·승인 등)",
      "sourceRef": "보세사 기출 2과목(보세구역관리): 2024년 17번(특허보세구역 설치·운영 신청인 요건 — 결격사유 부존재 포함), 2025년 22번(보세창고 신청인 요건 — 실형 결격기간 '1년'(오)/'2년'(정) 함정). 출처 kinz.kr, bosesa-data-2-2024.js·bosesa-data-2-2025.js (claude/previews/tradelogix-nexus)"
