        "재해로 멸실된 때에는 그 운영인이나 보관인으로부터 즉시 그 관세를 징수한다.",
        "세관장은 급박하여 화주에게 폐기 통고할 여유가 없는 경우에는 폐기한 후 즉시통고 하여야 한다."
