      "lawBasis": "관세법 제160조(장치물품의 폐기) 제1항(폐기 시 세관장 승인), 제2항 본문(멸실·폐기 시 운영인·보관인으로부터 즉시 관세징수) 및 단서(재해 등 부득이한 사유로 멸실되거나 미리 승인받아 폐기한 때 미징수), 제3항(폐기 후 잔존물은 폐기 후의 성질·수량에 따라 관세 부과), 제4항(세관장의 폐기명령·통고 권한 및 급박하여 통고할 여유가 없는 경우 폐기 후 즉시 통고). 참고로 제5항은 통고할 수 없는 경우 공고로 갈음, 제6항은 폐기 비용을 화주등이 부담하는 규정이다.",
