      "lawBasis": "관세법 제183조(보세창고) 제1항(장치대상: 외국물품·통관하려는 물품)·제2항 본문(미리 세관장에게 신고 후 내국물품 장치)·제2항 단서(동일 보세창고에 장치 중 수입신고가 수리된 물품은 신고 없이 계속 장치 가능)·제3항(1년/6개월 이상 계속하여 내국물품만 장치 시 세관장 승인), 제184조(장치기간이 지난 내국물품) 제1항(제183조 제2항에 따른 내국물품의 장치기간 경과 후 10일 내 운영인 책임 반출)·제2항(제183조 제3항에 따라 승인받은 내국물품도 승인기간 경과 시 제1항 준용)",
