        "설치 기관 혼동 주의: 제도운영위원회=기획재정부, 특허심사위원회=관세청.",
        "발문이 '틀린 것'을 묻는지 '맞는 것'을 묻는지부터 확인 — 본 문제는 '틀린 것' 찾기이며, 맞는 선지가 4개라 자칫 발문 방향을 놓치면 오답으로 빠진다."
